def get_prime_factors(x):
    """Get all prime factors of x"""
    factors = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

def get_prime_count(x, p):
    """Count how many times prime p divides x"""
    count = 0
    while x > 0 and x % p == 0:
        count += 1
        x //= p
    return count

