            for j in range(c, c + size):
                if matrix[r][j] == 0 or matrix[r + size - 1][j] == 0:
                    return False
            # Check left and right columns (excluding corners)
            for i in range(r + 1, r + size - 1):
                if matrix[i][c] == 0 or matrix[i][c + size - 1] == 0:
                    return False

            # Check interior must be all 0
            for i in range(r + 1, r + size - 1):
                for j in range(c + 1, c + size - 1):
                    if matrix[i][j] == 1:
                        return False

