                        continue
                    for i in range(size):
                        nr, nc = r + dr, c + dc + i
                        if dr != 0 or dc != 0:
                            nnr, nnc = r + size - 1 + dr, c + size - 1 + dc
                            if dr != 0 or dc != 0:
                                nnr, nnc = r + dr + i, c + size - 1 + dc

                            if nnr >= 0 and nnr < n and nnc >= 0 and nnc < m:
                                if matrix[nnr][nnc] == 1:
                                    return False

            return True

        def is_valid_diagonal(cr, cc, k):
            # k is the "size" (number of rows spanning) for the diagonal square
            # For a diagonal square, border cells satisfy: |r - cr| + |c - cc| = k // 2
            border_dist = k // 2

            if border_dist == 0:
                return True

            valid = True

            # Check all cells with Manhattan distance exactly border_dist form border (must be 1)
            for r in range(cr - border_dist, cr + border_dist + 1):
                for c in range(cc - border_dist, cc + border_dist + 1):
                    if abs(r - cr) + abs(c - cc) == border_dist:
                        if matrix[r][c] == 0:
                            return False

            # Check interior (distance < border_dist) must be all 0
            for r in range(cr - border_dist, cr + border_dist):
                for c in range(cc - border_dist, cc + border_dist):
                    if abs(r - cr) + abs(c - cc) < border_dist:
                        if matrix[r][c] == 1:
                            return False

            # Check no foreign 1s touching (cells at distance border_dist + 1)
            for r in range(max(0, cr - border_dist - 1), min(n, cr + border_dist + 2)):
                for c in range(max(0, cc - border_dist - 1), min(m, cc + border_dist + 2)):
                    if abs(r - cr) + abs(c - cc) == border_dist + 1:
                        if matrix[r][c] == 1:
                            return False

            return True

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if is_valid_axis_aligned(r, c, size):
