        curr = start
        while curr != 0:
            if curr in path:
                return True  # Cycle detected
            if curr in visited:
                return False  # Already processed, no cycle
            visited.add(curr)
            path.add(curr)
            curr = next_after[curr]
        path.remove(start)
        return False

    # Check all nodes that have a next pointer
    for i in range(1, n + 1):
        if next_after[i] != 0:
            if has_cycle(i):
                return '\n0\n'

    # Build chains from special pairs
    chains = []
    for i in range(1, n + 1):
        if next_after[i] == 0:  # Start of chain (no node comes after this node in special pairs)
            chain = []
            curr = i
            while curr != 0:
                chain.append(curr)
                curr = next_after[curr]
            chains.append(chain)

    # Topological sort with special pair constraints
    # For each topic, track in-degree based on prerequisites
    in_degree = [0] * (n + 1)
    adj = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        prereq = p[i - 1]
        if prereq != 0:
            adj[prereq].append(i)
            in_degree[i] += 1

    # Done tracks nodes already in result
    done = [False] * (n + 1)
    result = []

    # Process by in-degree 0 nodes
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]

    while queue:
        # Find the chain that starts with this node
        for start in list(queue):
            if done[start] or next_after[start] != 0:
                continue

            # Try to add this chain
            can_add = True
            for node_idx in range(len(chains)):
                chain = chains[node_idx]
                if chain[0] == start:
                    # Verify all prerequisites satisfied for this chain
                    for node in chain:
                        prereq = p[node - 1]
                        if prereq != 0 and not done[prereq]:
                            can_add = False
                            break
                    if can_add:
                        # Add entire chain
                        for node in chain:
                            result.append(node)
                            done[node] = True
                            # Decrement in-degrees
                            for neighbor in adj[node]:
                                in_degree[neighbor] -= 1
                            for neighbor in adj[node]:
                                if in_degree[neighbor] == 0 and not done[neighbor]:
                                    pass  # Will be added when we process it
                        break

    # Handle any remaining nodes
    for i in range(1, n + 1):
        if not done[i]:
            # This should not happen if valid, but just in case add in order
            result.append(i)
            done[i] = True

    # Verify all nodes used exactly once and special pairs satisfied
    if len(result) != n or len(set(result)) != n:
        return '\n0\n'

    # Verify special pairs are satisfied consecutively
    for x, y in pairs:
        try:
            idx_x = result.index(x)
            if result[idx_x + 1] != y:
                return '\n0\n'
        except:
            return '\n0\n'

    return '\n' + ' '.join(map(str, result)) + '\n'

