def get_move_direction(move, swapLR=0, swapUD=0):
    """Get the actual direction deltas after swap."""
    if swapUD:
        if move == 'U':
            return (1, 0)  # U becomes D
        elif move == 'D':
            return (-1, 0)  # D becomes U
    else:
        if move == 'U':
            return (-1, 0)
        elif move == 'D':
            return (1, 0)

    if swapLR:
        if move == 'L':
            return (0, 1)  # L becomes R
        elif move == 'R':
            return (0, -1)  # R becomes L
    else:
        if move == 'L':
            return (0, -1)
        elif move == 'R':
            return (0, 1)

    return (0, 0)

