def solution(input_data):
    lines = input_data.strip().split('\n')
    t = int(lines[0])
    results = []

    def check_all_illuminated(n, p, directions):
        for i in range(n):
            illuminated = False
            for j in range(i - 1, -1, -1):
                if directions[j] == 'R' and i - j <= p[j]:
                    illuminated = True
                    break
            if not illuminated:
                for j in range(i + 1, n):
                    if directions[j] == 'L' and j - i <= p[j]:
                        illuminated = True
                        break

            if not illuminated:
                return False
        return True

    idx = 1
    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        p = list(map(int, lines[idx].split()))
        idx += 1

        # Build result by trying patterns
        directions = ['R'] * n
        covered = [False] * n
        possible = True

        # Process each position
        for i in range(n):
            if covered[i]:
                continue

            # Try to pair with next position or find coverage
            can_move_right = False
            can_move_left = False

            if i < n - 1 and p[i] > 0:
                # Check if we can point right to illuminate i+1
                if not covered[i + 1]:
                    can_move_right = True

            if i > 0 and covered[i - 1] and p[i - 1] > 0 and i - 1 + p[i-1] >= i:
                can_move_left = True

            if can_move_right:
                directions[i] = 'R'
                for j in range(i + 1, min(n, i + p[i] + 1)):
                    covered[j] = True
            elif can_move_left:
                directions[i] = 'L'
                for j in range(max(0, i - p[i]), i):
                    covered[j] = True
            else:
                possible = False

        if not possible:
            # Try different pattern - greedy from left
            directions = [''] * n
            covered = [False] * n

            for i in range(n):
                if covered[i]:
                    continue

                # Default to R, but check if L could help
                can_use_r = False
                can_use_l = False

                # Check right coverage
                for j in range(i + 1, min(n, i + p[i] + 1)):
                    if not covered[j]:
                        can_use_r = True

                # Check left coverage  
                for j in range(max(0, i - p[i]), i):
                    if not covered[j]:
                        can_use_l = True

                if can_use_l and can_use_r:
                    if can_use_r:
                        directions[i] = 'R'
                        for j in range(i + 1, min(n, i + p[i] + 1)):
                            covered[j] = True
                        covered[i] = True
                    else:
                        directions[i] = 'L'
                        for j in range(max(0, i - p[i]), i):
                            covered[j] = True
                        covered[i] = True
                elif can_use_r:
                    directions[i] = 'R'
                    for j in range(i + 1, min(n, i + p[i] + 1)):
                        covered[j] = True
                    covered[i] = True
                elif can_use_l:
                    directions[i] = 'L'
                    for j in range(max(0, i - p[i]), i):
                        covered[j] = True
                    covered[i] = True
                else:
                    possible = False
                    break

        if not possible or not check_all_illuminated(n, p, directions):
            # Try different approach - alternating L/R within groups
            possible = False
            directions = [''] * n
            covered = [False] * n

            # Greedy pairing: find consecutive lit pairs
            wrote = False
            for i in range(n - 1):
                if p[i] > 0 and p[i+1] > 0 and not covered[i] and not covered[i+1]:
                    directions[i] = 'R'
                    directions[i+1] = 'L'
                    for j in range(i+1, min(n, i + 1 + p[i])):
                        covered[j] = True
                    for j in range(i - 1, max(-1, i + 1 - p[i+1] - 1), -1):
                        covered[j] = True
                    wrote = True

            # Final validation
            if not check_all_illuminated(n, p, directions):
                pass
            else:
                possible = True
        else:
            possible = True

        if not possible:
            results.append("NO")
        else:
            results.append("YES")
            results.append(''.join(directions))

    return '\n'.join(results)

def solution(X_str):
    """
    Compute sum of S(n) for n from 1 to X, modulo 10^9 + 7
    where S(n) sorts the digits of n in ascending order.
    """
    mod = 10**9 + 7

    def s_val(n):
        # Sort digits of n and convert back to integer
        digits = sorted(str(n))
        return int(''.join(digits))

    result = 0
    X = int(X_str)

    # Compute sum from 1 to X
    for n in range(1, X + 1):
        result = (result + s_val(n)) % mod

    return str(result)

