def solution(input_str):
    n, r = map(int, input_str.strip().split())

    # Generate all valid integer points within distance r
    points_list = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points_list.append((x, y, x*x + y*y))

    best_score = -1
    best_config = None

    def calc_score(config):
        """Calculate sum of squared pairwise distances"""
        sz = len(config)
        total_norm = 0
        sum_x = 0
        sum_y = 0
        for x, y, norm in config:
            total_norm += norm
            sum_x += x
            sum_y += y

        # Formula: n * sum(||p_i||^2) - ||sum p_i||^2 gives sum over all ordered pairs
        # For unordered pairs, it's half: (n - 1) * sum(||p_i||^2) - ||sum p_i||^2
        # Actually for C(n,2) = n(n-1)/2 pairs, we get:
        # n * sum_norms - ||sum_vec||^2

        return n * total_norm - (sum_x * sum_x + sum_y * sum_y)

    # Brute force for small n (n <= 8, so max ~8 choose 8 = 1 combo of distinct, 
    # but with repetition allowed, it's n^n which is manageable for n=8)
    if n <= 5:
        def backtrack(idx, current, start_len):
