                return

            available = points_list[start_len:]
            for (x, y, sq) in available:
                # Can possibly allow repetition - check allowed positions
                current.append((x, y, sq))
                backtrack(idx + 1, current, start_len if len(current) == n else start_len)
                current.pop()

        # For small n, try various strategies
        # Strategy 1: All same point at max distance
        if points_list:
            max_point = None
            for p in points_list:
                if p[2] == r*r:
                    max_point = p
                    break

            if max_point:
                test_config = [max_point] * n
                score = calc_score(test_config)
                if score > best_score:
                    best_score = score
                    best_config = test_config

        # Strategy 2: Opposite pairs
        if len(points_list) >= 2:
            max_dist = r * r * 2
            # Find opposite pairs at max distance
            pairs_found = []
            m = len(points_list)
            for i in range(m):
                for j in range(i + 1, m):
                    x1, y1, _ = points_list[i]
                    x2, y2, _ = points_list[j]
                    if x1 + x2 == 0 and y1 + y2 == 0:
                        pairs_found.append([(x1, y1), (x2, y2)])

            if pairs_found:
                num_pairs = n // 2
                for i in range(min(num_pairs, len(pairs_found))):
                    config = []
                    for _ in range(n // 2):
                        if i < len(pairs_found):
                            config.append(pairs_found[i][0])
                            config.append(pairs_found[i][1])
                        else:
                            config.append(points_list[0])

                    score = calc_score(config)
                    if score > best_score:
                        best_score = score
                        best_config = config

    # Try more exhaustive search: assign each tower to a point
    if best_config is None or n <= 7:
        best_score = -1
        best_config = None
        for assignment in combinations_with_replacement(points_list, n):
            score = calc_score(list(assignment))
            if score > best_score:
                best_score = score
                best_config = list(assignment)

    # Format output
    output_lines = [str(best_score)]
    for x, y, _ in best_config:
        output_lines.append(f"{x} {y}")

    return '\n'.join(output_lines)

