def solution(input_str):
    N = int(input_str)

    def digital_root(x):
        return 9 if x % 9 == 0 else x % 9

    # Count numbers in [1, N] with each digital root
    count_by_dr = [0] * 10
    for r in range(1, 10):
        if r > N:
            count_by_dr[r] = 0
        else:
            # Numbers with digital root r: r, r+9, r+18, ...
            count_by_dr[r] = (N - r) // 9 + 1

    result = 0
    for A in range(1, N + 1):
        for B in range(1, N + 1):
            dr = digital_root(A * B)
            if A * B <= N:
                # AB = C is exact, subtract 1 from count
                result += count_by_dr[dr] - 1
            else:
                # AB > N, no exact match possible
                result += count_by_dr[dr]

    return str(result) + "\n"
